// Builds the render request. Values come from the webhook body when called by another
// workflow/app (POST {topic, items, layout, brand, ...}); the defaults below are for manual runs.
let renderer = 'http://reel-factory:3077'; // VPS: renderer container on the docker network
try { renderer = $env.REEL_FACTORY_URL || renderer; } catch (e) { /* env access blocked: keep default */ }
const input = $json.body ?? {};
const samples = `${renderer}/samples/vocab-bedroom`;

const items = input.items ?? [
  { image: `${samples}/duvet.png`, word: 'Duvet', ipa: '/duːˈveɪ/' },
  { image: `${samples}/alarm-clock.png`, word: 'Alarm clock', ipa: '/əˈlɑrm klɑk/' },
  { image: `${samples}/wardrobe.png`, word: 'Wardrobe', ipa: '/ˈwɔrˌdroʊb/' },
  { image: `${samples}/bed.png`, word: 'Bed', ipa: '/bɛd/' },
];

return [{
  json: {
    renderer,
    request: {
      template: 'vocab-quiz',
      layout: input.layout ?? 'classic',
      brand: input.brand ?? {
        name: 'FluentHub',
        website: 'fluenthub.app',
        primaryColor: '#1d3b40',
        accentColor: '#43a41a',
        wordmark: ['Fluent', 'Hub'],
      },
      voice: input.voice ?? { provider: 'piper', voice: 'en_US-lessac-medium' },
      output: input.output ?? { fps: 30, quality: 'standard' },
      data: {
        title: input.title ?? 'What is this called?',
        flag: input.flag ?? 'us',
        items,
        engagement: input.engagement ?? { enabled: true, text: 'Let me know in the comments!' },
        cta: input.cta ?? { headline: 'Way more than vocab', image: `${samples}/app-phones.png` },
        sounds: input.sounds ?? { countdown: 'tick' },
      },
      meta: { topic: input.topic ?? 'Bedroom', executionId: $execution.id },
    },
  },
}];

// The renderer POSTs the finished job to this execution's resume URL.
const job = $json.body ?? $json;
if (job.status !== 'done') {
  throw new Error(`Render failed: ${job.error || job.status}`);
}
return [{ json: { videoUrl: job.videoUrl, thumbnailUrl: job.thumbnailUrl, duration: job.duration, renderSeconds: job.renderSeconds, jobId: job.id, meta: job.meta } }];
